import { readFile } from 'node:fs/promises';
import { dirname, join } from 'node:path';
import { fileURLToPath } from 'node:url';
import {
    assertNoOrphanContentModules,
    assertOrderMatchesClosure,
    bundleDependencyClosure,
    resolveBundleOrder,
} from './bundle-deps.mjs';

const root = join(dirname(fileURLToPath(import.meta.url)), '../..');

let cachedOrder = null;

/** Concatenation order for release `content.js` (derived from `content.js` import graph). */
export async function getBundleOrder() {
    if (!cachedOrder) {
        const order = await resolveBundleOrder();
        const closure = await bundleDependencyClosure();
        assertOrderMatchesClosure(order, closure);
        await assertNoOrphanContentModules(order);
        cachedOrder = order;
    }
    return cachedOrder;
}

/** @deprecated use getBundleOrder() — kept for duplicate-binding scan */
export const BUNDLE_ORDER = null;

export function stripModuleSyntax(source) {
    return source
        .replace(/^import\s[\s\S]*?from\s+['"][^'"]+['"];?\s*$/gm, '')
        .replace(/^export\s+\{[^}]*\}\s*;?\s*$/gm, '')
        .replace(/^export\s+default\s+/gm, '')
        .replace(/^export\s+(?=async\s+function|function|class|const|let|var)/gm, '');
}

export async function readFirefoxContentBundle(version) {
    const order = await getBundleOrder();
    const parts = [
        `/* job-xray ${version} content bundle. Generated by scripts/build.mjs. Do not edit. */`,
        ...(await Promise.all(order.map((rel) => readFile(join(root, rel), 'utf8')))).map(
            stripModuleSyntax,
        ),
    ];
    return parts.join('\n');
}
